// Generated by tools/battle_entrance.py. Coordinates relative to battle body.
export const battleEntryDuration=1000;
const whole=(a,b)=>Math.floor(a/b);
export function battleEntryState(time){

 let opacity=time<360?0:time<720?whole((time-360)*255,360):255;
 let white=time<500?255:time<880?255-whole((time-500)*255,380):0;
 let drop=time<360?6:time<720?6-whole((time-360)*6,360):0;
return {opacity,white,drop};
}
export function battleEntryPaint(side,time,paint){const data=null;

 if(time>=1000)return;
 let flight=time<300?time:300;
 let x=side?336-whole(flight*56,300):24+whole(flight*56,300);
 let arc=flight<150?whole(flight*14,150):whole((300-flight)*14,150);
 let y=136-arc;
 if(time<500){
  let gap=time<300?0:whole((time-300)*8,200);
  paint(data,x-6,y-8-gap,12,2,0x182a38,255);
  paint(data,x-8,y-6-gap,16,5,0x182a38,255);
  paint(data,x-6,y-6-gap,12,4,0xed7968,255);
  paint(data,x-6,y-2-gap,12,2,0x182a38,255);
  paint(data,x-8,y+1+gap,16,5,0x182a38,255);
  paint(data,x-6,y+1+gap,12,4,0xd5e0e5,255);
  paint(data,x-6,y+6+gap,12,2,0x182a38,255);
  if(time<360){paint(data,x-3,y-3,6,6,0x182a38,255);paint(data,x-1,y-1,2,2,0xffffff,255);}
 }
 if(time>=340&&time<600){
  let alpha=time<480?220:whole((600-time)*220,120);
  paint(data,x-3,108,6,28,0xe9f8ff,alpha);
 }
 if(time>=360&&time<900){
  let radius=8+whole((time-360)*30,540),alpha=220-whole((time-360)*220,540);
  for(let i=0;i<6;i++){
   let dx=i<4?(i%2?1:-1):0,dy=i<4?(i<2?-1:1):(i==4?-1:1);
   let px=x+dx*radius,py=120+dy*radius;
   paint(data,px-2,py,5,1,i%2?0xffedb3:0xc9f4ff,alpha);
   paint(data,px,py-2,1,5,i%2?0xffedb3:0xc9f4ff,alpha);
  }
 }
}
